#pragma once
// Disc image check (docs/SETUP.md "Disc image check"): every file of the user's disc image is
// compared (size, CRC-32) with the retail disc's (tables generated by tools/gen_disc_files.py).
// Setup only checks the main.dol; a damaged or modified image with a retail DOL used to start
// and then crash in game data (issue #37: a broken file-select archive crashed at START on the
// title screen, "call to null (lr=80047B20)"). The result is cached per image (path, size,
// modification time) in <dataDir>/disc_check_<ID>.txt, so the files are read once.
#include "port/install.h"

#include <atomic>
#include <functional>
#include <optional>
#include <string>
#include <vector>

namespace setup {

struct DiscCheck {
    int files = 0;                 // retail files compared
    std::vector<std::string> bad;  // "<path> (missing|size|contents|unreadable)"
    bool accepted = false;         // the user chose to play with this image anyway
    bool ok() const { return bad.empty(); }
    // "3 of 847 game files differ from the retail disc: /a (contents), /b (size), ..."
    std::string summary(size_t maxNames = 4) const;
};

// The cached result for this image, if it is still the same file.
std::optional<DiscCheck> cachedDiscCheck(const std::string& utf8Path, port::GameVersion v);
// Reads every retail file of the image (progress 0..1; cancel stops early, returning nullopt).
std::optional<DiscCheck> checkDiscFiles(const std::string& utf8Path, port::GameVersion v,
                                        const std::atomic<bool>* cancel, const std::function<void(float)>& progress);
void saveDiscCheck(const std::string& utf8Path, port::GameVersion v, const DiscCheck& check);
// LM_DISC_CHECK=0 skips the check (test aid); LM_DISC_CHECK=force ignores the cache.
bool discCheckEnabled();
bool discCheckForced();

}  // namespace setup
